function f(x: string | null) {
  if (x === null) return;
  x.toUpperCase(); // x narrowed to string here
}

function pad(v: string | number) {
  if (typeof v === 'number') return ' '.repeat(v);
  return v; // v: string
}

function start(d: Date | string) {
  if (d instanceof Date) return d.getTime();
  return Date.parse(d);
}

function move(a: { swim(): void } | { fly(): void }) {
  if ('swim' in a) a.swim(); else a.fly();
}

function len(s?: string) {
  if (s) return s.length; // s: string (no undefined)
  return 0;
}

function isString(x: unknown): x is string {
  return typeof x === 'string';
}

function assertNever(x: never): never {
  throw new Error('Unhandled: ' + x);
}

