function format(v: string | number | null): string {
  if (v === null) return 'none';
  if (typeof v === 'number') return 'num:' + v.toFixed(1);
  return 'str:' + v.toUpperCase(); // v narrowed to string
}

console.log(format(3));
console.log(format('hi'));
console.log(format(null));

type Fish = { swim: () => string };
type Bird = { fly: () => string };

function move(animal: Fish | Bird): string {
  if ('swim' in animal) return animal.swim();
  return animal.fly();
}

console.log(move({ swim: () => 'swimming' }));
console.log(move({ fly: () => 'flying' }));

