function handle(input: string | number) {
  let value = input;
  if (typeof value === 'string') {
    // value is string here
    setTimeout(() => {
      // BUG: inside the callback, value is back to string | number
      console.log(value.toUpperCase()); // not safe per the type system
    }, 0);
    value = 0; // reassignment is why TS can't trust the narrowing
  }
}

handle('hello');

solution.code:
function handle(input: string | number) {
  if (typeof input === 'string') {
    const str = input; // const captures the narrowed string type
    setTimeout(() => {
      console.log(str.toUpperCase()); // safe: str is string
    }, 0);
  }
}

handle('hello');

type Circle = { kind: 'circle'; radius: number };
type Square = { kind: 'square'; side: number };
type Shape = Circle | Square;

function assertNever(x: never): never {
  throw new Error('Unhandled shape: ' + JSON.stringify(x));
}

function area(shape: Shape): number {
  switch (shape.kind) {
    case 'circle': return Math.PI * shape.radius ** 2;
    case 'square': return shape.side ** 2;
    default: return assertNever(shape);
  }
}

console.log(area({ kind: 'circle', radius: 2 }).toFixed(2));
console.log(area({ kind: 'square', side: 3 }));
